const d = $input.first().json;
let arr = [];
try { arr = (typeof d.ingredients === 'string') ? JSON.parse(d.ingredients) : (d.ingredients || []); } catch (e) { arr = []; }
if (!Array.isArray(arr)) arr = [];
const names = arr.map(x => (x && typeof x === 'object') ? String(x.item || '') : String(x || '')).map(s => s.trim()).filter(Boolean);
return [{ json: { bot_id: d.bot_id, user_id: d.user_id, names } }];

const names = $('Разобрать').first().json.names || [];
const row = $input.first().json || {};
let al = row.allergens; if (typeof al === 'string') { try { al = JSON.parse(al); } catch (e) { al = []; } }
al = al || [];
if (!al.length) return [{ json: { response: 'У клиента в карте нет аллергий/непереносимостей — ингредиенты по этому критерию допустимы. Всё равно опирайся на здравый смысл.' } }];
const hits = [];
for (const nm of names) { const n = String(nm).toLowerCase(); for (const a of al) { if (a.substance && n.indexOf(a.substance) !== -1) hits.push({ ing: nm, allergen: a.substance, severity: a.severity }); } }
if (!hits.length) return [{ json: { response: 'Аллергенов клиента в ингредиентах НЕ найдено (по явным вхождениям). ВНИМАНИЕ: скрытые аллергены в составных продуктах (марципан→миндаль и т.п.) так не ловятся — при серьёзной аллергии добавь оговорку клиенту.' } }];
const block = hits.filter(h => h.severity === 'allergy');
const warn = hits.filter(h => h.severity === 'intolerance');
const parts = [];
if (block.length) parts.push('БЛОКИРОВКА (аллергия!): ' + block.map(h => h.ing + ' → ' + h.allergen).join('; ') + '. НЕ предлагай этот рецепт, замени ингредиент на безопасный.');
if (warn.length) parts.push('Предупреждение (непереносимость): ' + warn.map(h => h.ing + ' → ' + h.allergen).join('; ') + '. Предупреди клиента или замени.');
return [{ json: { response: parts.join(' ') } }];
